SELECT DISTINCT pb.* FROM leetcode_problem_bank pb LEFT JOIN leetcode_problem_tag pt ON pt.problem_id = pb.id
AND (pb.title_main LIKE CONCAT('%', #{keyword}, '%') OR pb.problem_code LIKE CONCAT('%', #{keyword}, '%') OR pt.tag_value LIKE CONCAT('%', #{keyword}, '%'))
AND pb.difficulty = #{difficulty}
ORDER BY pb.numeric_id ASC, pb.id ASC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(DISTINCT pb.id) FROM leetcode_problem_bank pb LEFT JOIN leetcode_problem_tag pt ON pt.problem_id = pb.id
AND (pb.title_main LIKE CONCAT('%', #{keyword}, '%') OR pb.problem_code LIKE CONCAT('%', #{keyword}, '%') OR pt.tag_value LIKE CONCAT('%', #{keyword}, '%'))
AND pb.difficulty = #{difficulty}
